(async()=>{if(new URLSearchParams(location.search).get('profile')!=='camp-meadow-check')return;while(!window.EmberQA)await new Promise(r=>setTimeout(r,100));const q=EmberQA,D=SurvivalData,W=EmberTerrain;document.getElementById('welcome').hidden=true;q.setPlaying(false);const report=document.createElement('pre');report.id='camp-report';report.style='position:fixed;top:12px;left:12px;z-index:100;background:#fff;color:#243b35;padding:12px;font-size:12px;max-width:40vw';document.body.append(report);const result={},check=(k,v)=>{result[k]=!!v;report.textContent=JSON.stringify(result,null,2);if(!v)throw Error(k);};try{
q.apply({...D.fresh(),inventory:{hammer:1,wood:3,fiber:6},hand:'hammer',automaticTime:false});let p;outer:for(let z=10;z<160;z+=3)for(let x=-100;x<100;x+=3){const v={x,z,y:W.ground(x,z)};if(!q.tentPlacement(v)&&q.world.tentFrame(v).angle>6){p=v;break outer;}}check('gentleSlopePlacement',p);Object.assign(q.state,{x:p.x,z:p.z+3,y:W.ground(p.x,p.z+3),yaw:0});q.deposit('tent');const pile=q.state.piles.find(v=>v.items.fiber===6);check('materialsDeposited',pile&&!q.state.inventory.wood);q.craft(pile.id,'tent');const job=q.state.jobs.find(v=>v.type==='tent');check('constructionStarted',job);q.work(job,10);let tent=q.state.structures.find(v=>v.type==='tent');check('builtWithHammer',tent?.progress===1&&!q.state.jobs.length);check('daySleepRefused',!q.sleepTent(tent.id));check('doorOpen',!q.world.blocked(tent.x,tent.z+1.9,tent.y,q.state));check('canvasSolid',q.world.blocked(tent.x+1.6,tent.z,tent.y,q.state));check('tentTilted',q.world.tentFrame(tent).angle>6);q.state.checkpoint={id:'qa',x:p.x,y:p.y,z:p.z};check('unusedSave',q.saveSlot(19));q.loadSlot(19);tent=q.state.structures.find(v=>v.type==='tent');check('restoreUnusedTent',tent?.progress===1);q.setPlaying(false);q.state.worldTime=21/24*720;q.sky.restore(q.state);q.state.stamina=12;q.tentMenu(tent);document.querySelector('[data-action="tentsleep:'+tent.id+'"]').click();check('sleepToNextMorning',Math.abs(q.sky.cycle.worldDays-(1+7/24))<.001&&q.state.stamina===100);check('singleUseRemoved',!q.state.structures.some(v=>v.id===tent.id));check('reuseRefused',!q.sleepTent(tent.id));q.state.structures.push({...tent,id:'second'});q.syncObjects();q.state.worldTime=(2+2/24)*720;q.sky.restore(q.state);check('afterMidnightSleep',q.sleepTent('second')&&Math.abs(q.sky.cycle.worldDays-(2+7/24))<.001);q.state.checkpoint={id:'qa',x:p.x,y:p.y,z:p.z};check('save',q.saveSlot(19));q.loadSlot(19);check('consumedStaysRemoved',!q.state.structures.some(v=>v.type==='tent'));q.state.structures.push({...tent,id:'preview'});q.syncObjects();q.setPlaying(false);q.close(false);q.camera.position.set(p.x+5,p.y+3,p.z+7);q.camera.lookAt(p.x,p.y+1,p.z);q.sky.update(q.state,0,true);q.renderer.render(q.scene,q.camera);result.complete=true;report.textContent=JSON.stringify(result,null,2);const hide=document.createElement('button');hide.textContent='確認表示を閉じる';hide.style='position:fixed;top:12px;right:12px;z-index:200';hide.onclick=()=>{report.hidden=true;hide.remove();};document.body.append(hide);
}catch(e){report.textContent+='\nFAIL '+e.stack;}})();
